python - <<'EOF'
import math
from wire.codec import encode, decode, CodecError
recs = [{"ts": 5, "sensor_id": 9, "value": -0.0, "flags": 1}]
data = encode(recs)
print("bytes per 1 record:", len(data))
print("neg zero sign kept:", math.copysign(1, decode(data)[0]["value"]) == -1)
flipped = sum(1 for i in range(len(data)) for _ in [0]
              if (lambda b: (lambda: (decode(b), False)[1])() if False else None) is None)
bad = 0
for i in range(len(data)):
    b = bytearray(data); b[i] ^= 0x01
    try: decode(bytes(b)); 
    except CodecError: bad += 1
print(f"bit flips caught: {bad}/{len(data)}")
for r in [{"ts": -1, "sensor_id": 0, "value": 0.0, "flags": 0},
          {"ts": 0, "sensor_id": 70000, "value": 0.0, "flags": 0},
          {"ts": 0, "sensor_id": 0, "value": "x", "flags": 0},
          {"ts": 0, "sensor_id": 0, "value": 0.0}]:
    try: encode([r]); print("NOT rejected:", r)
    except (ValueError, TypeError) as e: print("rejected:", e)
try: decode(data + b"\x00")
except CodecError as e: print("trailing rejected:", e)
EOF
git status --short

